// 命令 protocolgen 把 pkg/runtimeprotocol 的线上协议类型生成为前端使用的 TypeScript 文件。
package main

import (
	"fmt"
	"go/constant"
	"go/types"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"

	"github.com/coder/guts"
	"github.com/coder/guts/bindings"
	"github.com/coder/guts/config"

	"github.com/VaalaCat/openvaala/pkg/conversation"
	"github.com/VaalaCat/openvaala/pkg/runtime"
	"github.com/VaalaCat/openvaala/pkg/runtimeprotocol"
	"github.com/VaalaCat/openvaala/pkg/skill"
)

const packagePrefix = "github.com/VaalaCat/openvaala/pkg/"

// generatedHeader 是生成文件的第一行；guts 自带的 Code generated 头不保留。
const generatedHeader = "// 由 internal/protocolgen 生成，不要手改\n\n"

const gutsHeader = "// Code generated by 'guts'. DO NOT EDIT.\n\n"

// referencedPackages 是协议类型引用到的其他包，只生成被引用到的类型。
var referencedPackages = []string{
	"agent", "conversation", "dao", "defs", "executor", "hook", "mcpclient", "runtime", "session", "skill", "storage",
}

// externalTableTypesName 是 ExternalTableTypes 在生成结果里的名字。
const externalTableTypesName = "ExternalTableTypes"

// tableOnlyTypes 是 runtimeprotocol 里只服务方法表和通知表的 Go 类型，不属于线上数据。
var tableOnlyTypes = []string{
	packagePrefix + "runtimeprotocol.Method",
	packagePrefix + "runtimeprotocol.Notification",
}

// ExternalTableTypes 列出方法表直接返回、但 runtimeprotocol 里没有任何字段引用的其他包类型。
// guts 只生成被引用到的类型，所以靠这个结构体的字段让它们被生成；结构体本身不写进输出。
// 方法表新增这样的类型时，writeTables 会报 not generated，到这里补一个字段。
type ExternalTableTypes struct {
	RunningConversations runtime.RunningConversations
	ModelList            runtime.ModelList
	SessionContextUsage  runtime.SessionContextUsage
	SetDefinitionsResult runtime.SetDefinitionsResult
	SessionDetails       conversation.SessionDetails
	WorkspaceDirectories conversation.WorkspaceDirectories
	SkillInfo            skill.SkillInfo
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: protocolgen <output path>")
		os.Exit(2)
	}
	if err := writeProtocolTypes(os.Args[1]); err != nil {
		fmt.Fprintln(os.Stderr, "protocolgen:", err)
		os.Exit(1)
	}
}

// writeProtocolTypes 生成协议类型并写入 outputPath。
func writeProtocolTypes(outputPath string) error {
	// 1. 生成完整的 TypeScript 源码。
	source, err := generateProtocolTypes()
	if err != nil {
		return err
	}

	// 2. 创建输出目录并写文件。
	if err := os.MkdirAll(filepath.Dir(outputPath), 0o755); err != nil {
		return fmt.Errorf("create output directory: %w", err)
	}
	if err := os.WriteFile(outputPath, []byte(source), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", outputPath, err)
	}
	return nil
}

// generateProtocolTypes 返回 protocol.gen.ts 的完整内容。
func generateProtocolTypes() (string, error) {
	// 1. 解析 runtimeprotocol 和它引用到的包，runtimeprotocol 里的类型全部生成。
	golang, err := guts.NewGolangParser()
	if err != nil {
		return "", fmt.Errorf("create golang parser: %w", err)
	}
	golang.PreserveComments()
	golang.IncludeCustomDeclaration(map[string]guts.TypeOverride{
		"encoding/json.RawMessage": config.OverrideLiteral(bindings.KeywordUnknown),
	})
	if err := golang.IncludeCustom(map[string]string{
		"github.com/VaalaCat/ai-gateway/pkg/llmkit/ir.Role": "string",
		"time.Time": "string",
	}); err != nil {
		return "", fmt.Errorf("map custom types: %w", err)
	}
	if err := golang.ExcludeCustom(tableOnlyTypes...); err != nil {
		return "", fmt.Errorf("exclude table only types: %w", err)
	}
	if err := golang.IncludeGenerate(packagePrefix + "runtimeprotocol"); err != nil {
		return "", fmt.Errorf("include runtimeprotocol: %w", err)
	}
	if err := golang.IncludeGenerate("github.com/VaalaCat/openvaala/internal/protocolgen"); err != nil {
		return "", fmt.Errorf("include protocolgen: %w", err)
	}
	for _, name := range referencedPackages {
		if err := golang.IncludeReference(packagePrefix+name, ""); err != nil {
			return "", fmt.Errorf("include reference %s: %w", name, err)
		}
	}

	// 2. 转成 TypeScript，枚举写成联合类型，按名字排序后序列化。
	ts, err := golang.ToTypescript()
	if err != nil {
		return "", fmt.Errorf("convert to typescript: %w", err)
	}
	ts.ApplyMutations(config.ExportTypes, config.EnumAsTypes, config.SimplifyOmitEmpty, addReferencedEnumUnions(golang))
	declarations, err := ts.SerializeInOrder(sortSupportedNodes)
	if err != nil {
		return "", fmt.Errorf("serialize typescript: %w", err)
	}

	// 3. 拼上文件头、方法表、通知表和 JSON-RPC 错误码。
	var source strings.Builder
	source.WriteString(generatedHeader)
	source.WriteString(strings.TrimPrefix(declarations, gutsHeader))
	if err := writeTables(&source, ts); err != nil {
		return "", err
	}
	writeErrorCodes(&source)
	return source.String(), nil
}

// addReferencedEnumUnions 把被引用包里带常量的命名类型补成常量值的联合类型。
func addReferencedEnumUnions(golang *guts.GoParser) guts.MutationFunc {
	return func(ts *guts.Typescript) {
		for _, pkg := range golang.Pkgs {
			if !golang.Reference[pkg.PkgPath] {
				continue
			}

			// 1. 按常量名顺序收集每个命名类型的常量值（guts 不读被引用包的常量，这些类型会退化成 string）。
			scope := pkg.Types.Scope()
			members := make(map[string][]bindings.ExpressionType)
			for _, name := range scope.Names() {
				enumConstant, ok := scope.Lookup(name).(*types.Const)
				if !ok || !enumConstant.Exported() {
					continue
				}
				enumType, ok := enumConstant.Type().(*types.Named)
				if !ok {
					continue
				}
				var value any
				switch enumConstant.Val().Kind() {
				case constant.String:
					value = constant.StringVal(enumConstant.Val())
				case constant.Int:
					value, _ = constant.Int64Val(enumConstant.Val())
				default:
					continue
				}
				typeName := enumType.Obj().Name()
				members[typeName] = append(members[typeName], &bindings.LiteralType{Value: value})
			}

			// 2. 已生成的别名类型改成这些常量值的联合。
			for typeName, literals := range members {
				node, ok := ts.Node(golang.Prefix[pkg.PkgPath] + typeName)
				if !ok {
					continue
				}
				if alias, ok := node.(*bindings.Alias); ok {
					alias.Type = bindings.Union(literals...)
				}
			}
		}
	}
}

// sortSupportedNodes 按名字排序，并去掉 ExternalTableTypes 和 guts 无法序列化的负数常量（JSON-RPC 错误码由 writeErrorCodes 输出）。
func sortSupportedNodes(nodes map[string]bindings.Node) []bindings.Node {
	names := make([]string, 0, len(nodes))
	for name, node := range nodes {
		if name == externalTableTypesName || isNegativeConstant(node) {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)

	sorted := make([]bindings.Node, 0, len(names))
	for _, name := range names {
		sorted = append(sorted, nodes[name])
	}
	return sorted
}

// isNegativeConstant 节点是否是值为负数的常量声明？
func isNegativeConstant(node bindings.Node) bool {
	statement, ok := node.(*bindings.VariableStatement)
	if !ok {
		return false
	}
	for _, declaration := range statement.Declarations.Declarations {
		literal, ok := declaration.Initializer.(*bindings.LiteralType)
		if !ok {
			continue
		}
		if value, ok := literal.Value.(int64); ok && value < 0 {
			return true
		}
	}
	return false
}

// writeTables 把方法表和两个方向的通知表写成 MethodParams、MethodResult、NotificationParams、ClientNotificationParams 四个接口。
func writeTables(source *strings.Builder, ts *guts.Typescript) error {
	// 1. 方法名到参数类型、结果类型。
	methodParams := make([]tableEntry, 0, len(runtimeprotocol.Methods))
	methodResults := make([]tableEntry, 0, len(runtimeprotocol.Methods))
	for _, method := range runtimeprotocol.Methods {
		params, err := getTypeScriptTypeName(ts, method.Params)
		if err != nil {
			return fmt.Errorf("method %s params: %w", method.Name, err)
		}
		result, err := getTypeScriptTypeName(ts, method.Result)
		if err != nil {
			return fmt.Errorf("method %s result: %w", method.Name, err)
		}
		methodParams = append(methodParams, tableEntry{name: method.Name, typeName: params})
		methodResults = append(methodResults, tableEntry{name: method.Name, typeName: result})
	}

	// 2. 服务端通知、客户端通知名到参数类型。
	notificationParams, err := getNotificationEntries(ts, runtimeprotocol.ServerNotifications)
	if err != nil {
		return err
	}
	clientNotificationParams, err := getNotificationEntries(ts, runtimeprotocol.ClientNotifications)
	if err != nil {
		return err
	}

	// 3. 四张表依次写出。
	writeTable(source, "MethodParams", "每个请求方法的参数类型。", methodParams)
	writeTable(source, "MethodResult", "每个请求方法的结果类型。", methodResults)
	writeTable(source, "NotificationParams", "每种服务端通知的参数类型。", notificationParams)
	writeTable(source, "ClientNotificationParams", "每种客户端通知的参数类型。", clientNotificationParams)
	return nil
}

// getNotificationEntries 把一组通知转成名字到 TypeScript 参数类型的表行。
func getNotificationEntries(ts *guts.Typescript, notifications []runtimeprotocol.Notification) ([]tableEntry, error) {
	entries := make([]tableEntry, 0, len(notifications))
	for _, notification := range notifications {
		params, err := getTypeScriptTypeName(ts, notification.Params)
		if err != nil {
			return nil, fmt.Errorf("notification %s params: %w", notification.Name, err)
		}
		entries = append(entries, tableEntry{name: notification.Name, typeName: params})
	}
	return entries, nil
}

// writeErrorCodes 把 JSON-RPC 错误码写成 TypeScript 常量，值取自 runtimeprotocol.ErrorCode*。
func writeErrorCodes(source *strings.Builder) {
	// 1. 名字照 Go 常量名；值直接引用 Go 常量，Go 侧改名会编译失败。
	errorCodes := []struct {
		name string
		code int
	}{
		{"ErrorCodeParse", runtimeprotocol.ErrorCodeParse},
		{"ErrorCodeInvalidRequest", runtimeprotocol.ErrorCodeInvalidRequest},
		{"ErrorCodeMethodNotFound", runtimeprotocol.ErrorCodeMethodNotFound},
		{"ErrorCodeInvalidParams", runtimeprotocol.ErrorCodeInvalidParams},
		{"ErrorCodeRuntime", runtimeprotocol.ErrorCodeRuntime},
		{"ErrorCodeSessionBusy", runtimeprotocol.ErrorCodeSessionBusy},
		{"ErrorCodeConversationNotFound", runtimeprotocol.ErrorCodeConversationNotFound},
		{"ErrorCodeSessionNotFound", runtimeprotocol.ErrorCodeSessionNotFound},
		{"ErrorCodeTerminalNotFound", runtimeprotocol.ErrorCodeTerminalNotFound},
	}

	// 2. 逐个写出。
	for _, errorCode := range errorCodes {
		fmt.Fprintf(source, "export const %s = %d;\n", errorCode.name, errorCode.code)
	}
}

// tableEntry 是表里的一行：方法名或通知名，加对应的 TypeScript 类型。
type tableEntry struct {
	name     string
	typeName string
}

// writeTable 写出一个名字到类型的接口。
func writeTable(source *strings.Builder, interfaceName, comment string, entries []tableEntry) {
	fmt.Fprintf(source, "/**\n * %s\n */\nexport interface %s {\n", comment, interfaceName)
	for _, entry := range entries {
		fmt.Fprintf(source, "    %q: %s;\n", entry.name, entry.typeName)
	}
	source.WriteString("}\n\n")
}

// getTypeScriptTypeName 返回 Go 类型对应的 TypeScript 类型名，指针按所指类型处理，切片写成数组。
func getTypeScriptTypeName(ts *guts.Typescript, goType reflect.Type) (string, error) {
	switch goType.Kind() {
	case reflect.Pointer:
		return getTypeScriptTypeName(ts, goType.Elem())
	case reflect.Slice:
		elementName, err := getTypeScriptTypeName(ts, goType.Elem())
		return elementName + "[]", err
	}

	if _, ok := ts.Node(goType.Name()); !ok {
		return "", fmt.Errorf("type %s is not generated", goType)
	}
	return goType.Name(), nil
}
